  [7602] = {
    title = "Flawless Fel Essence",
    objectives = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.$B$BThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.$B$BRecover the Flawless Fel Essences and return  to Impsy in Felwood.",
  },
  [7603] = {
    title = "Kroshius\\' Infernal Core",
    objectives = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius\\' return. When the infernal has awoken, slay him and take from his corpse Kroshius\\' Infernal Core.$B$BReturn Kroshius\\' Infernal Core to Niby the Almighty in Felwood.",
