  [7701] = {
    title = "WANTED: Overseer Maltorius",
    objectives = "Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.$B$BSlay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.",
  },
  [7703] = {
    title = "Unfinished Gordok Business",
    objectives = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.$B$BAccording to Kromcrush, the \\",
  },
  [7704] = {
    title = "Look at the Size of It!",
    objectives = "Take Chambermaid Pillaclencher\\'s Pillow to Evonice Sootsmoker in the Searing Gorge.",
  },
  [7721] = {
    title = "Fuel for the Zapping",
    objectives = "Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.",
  },
  [7722] = {
    title = "What the Flux?",
    objectives = "Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge.",
  },
  [7723] = {
    title = "Curse These Fat Fingers",
    objectives = "Hansel Heavyhands wants you to kill 20 Heavy War Golems.$B$BThe Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you\\'ve killed enough, return to Hansel in Searing Gorge.",
  },
  [7724] = {
    title = "Fiery Menace!",
    objectives = "Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.$B$BReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.",
  },
  [7725] = {
    title = "Again With the Zapped Giants",
    objectives = "Use Zorbin\\'s Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form.  Bring 10 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.",
  },
  [7726] = {
    title = "Refuel for the Zapping",
    objectives = "Collect 6 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.",
  },
  [7727] = {
    title = "Incendosaurs? Whateverosaur is More Like It",
    objectives = "Hansel Heavyhands wants you to kill 20 Incendosaurs.$B$BYou will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.$B$BReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.",
  },
  [7728] = {
    title = "STOLEN: Smithing Tuyere and Lookout\\'s Spyglass",
    objectives = "Find and return the Smithing Tuyere and Lookout\\'s Spyglass to Taskmaster Scrange in the Searing Gorge.$B$BThe only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout\\'s Spyglass is an invaluable monitoring tool to lookouts. ",
  },
  [7729] = {
    title = "JOB OPPORTUNITY: Culling the Competition",
    objectives = "Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task.",
  },
  [7730] = {
